   public void setupAnim(The_Leviathan_Entity entityIn, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {
      this.animate(entityIn, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
      AdvancedModelBox[] tailBoxes = new AdvancedModelBox[]{this.Tail, this.Tail2, this.Tail3};
      float swimSpeed = 0.1F;
      float swimDegree = 0.4F;
      float finspeed = 0.1F;
      float finDegree = 0.2F;
      boolean swimAnimate = entityIn.isInWater();
      float partialTick = Minecraft.getInstance().getTimer().getGameTimeDeltaPartialTick(true);
      float LeftTentacleProgress = entityIn.prevLeftTentacleProgress + (entityIn.LeftTentacleProgress - entityIn.prevLeftTentacleProgress) * partialTick;
      float RightTentacleProgress = entityIn.prevRightTentacleProgress + (entityIn.RightTentacleProgress - entityIn.prevRightTentacleProgress) * partialTick;
      float NoswimProgress = entityIn.prevNoSwimProgress + (entityIn.NoSwimProgress - entityIn.prevNoSwimProgress) * partialTick;
      this.progressRotationPrev(this.R_fin, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(-15.0), 10.0F);
      this.progressRotationPrev(this.L_fin, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(15.0), 10.0F);
      this.progressRotationPrev(this.R_fin2, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(15.0), 10.0F);
      this.progressRotationPrev(this.L_fin2, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(-15.0), 10.0F);
      this.progressRotationPrev(this.R_down_fin, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(-50.0), 10.0F);
      this.progressRotationPrev(this.L_down_fin, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(50.0), 10.0F);
      this.progressRotationPrev(this.R_down_fin2, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(50.0), 10.0F);
      this.progressRotationPrev(this.L_down_fin2, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(-50.0), 10.0F);
      this.progressRotationPrev(this.R_mini_fin, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(-32.5), 10.0F);
      this.progressRotationPrev(this.L_mini_fin, NoswimProgress, 0.0F, 0.0F, (float)Math.toRadians(32.5), 10.0F);
      this.progressRotationPrev(this.LowerL_Tentacle, LeftTentacleProgress, 0.0F, 0.0F, (float)Math.toRadians(-32.5), 10.0F);
      this.progressRotationPrev(this.LowerR_Tentacle, RightTentacleProgress, 0.0F, 0.0F, (float)Math.toRadians(32.5), 10.0F);
      this.flap(this.UpperR_Hook, swimSpeed * 0.2F, 0.35F, true, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.swing(this.UpperR_Hook2, swimSpeed * 0.2F, 0.35F, true, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.swing(this.UpperR_Hook3, swimSpeed * 0.2F, 0.35F, false, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.flap(this.UpperR_Hook4, swimSpeed * 0.2F, 0.35F, false, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.flap(this.UpperR_Hook, swimSpeed * 1.3F, 0.35F, true, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.swing(this.UpperR_Hook2, swimSpeed * 1.3F, 0.35F, true, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.swing(this.UpperR_Hook3, swimSpeed * 1.3F, 0.35F, false, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.flap(this.UpperR_Hook4, swimSpeed * 1.3F, 0.35F, false, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.flap(this.UpperL_Hook, swimSpeed * 0.2F, 0.35F, false, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.swing(this.UpperL_Hook2, swimSpeed * 0.2F, 0.35F, false, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.swing(this.UpperL_Hook3, swimSpeed * 0.2F, 0.35F, true, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.flap(this.UpperL_Hook4, swimSpeed * 0.2F, 0.35F, true, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.flap(this.UpperL_Hook, swimSpeed * 1.3F, 0.35F, false, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.swing(this.UpperL_Hook2, swimSpeed * 1.3F, 0.35F, false, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.swing(this.UpperL_Hook3, swimSpeed * 1.3F, 0.35F, true, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.flap(this.UpperL_Hook4, swimSpeed * 1.3F, 0.35F, true, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.flap(this.LowerR_Hook, swimSpeed * 0.2F, 0.35F, true, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.swing(this.LowerR_Hook2, swimSpeed * 0.2F, 0.35F, true, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.swing(this.LowerR_Hook3, swimSpeed * 0.2F, 0.35F, false, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.flap(this.LowerR_Hook4, swimSpeed * 0.2F, 0.35F, false, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.flap(this.LowerR_Hook, swimSpeed * 1.3F, 0.35F, true, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.swing(this.LowerR_Hook2, swimSpeed * 1.3F, 0.35F, true, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.swing(this.LowerR_Hook3, swimSpeed * 1.3F, 0.35F, false, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.flap(this.LowerR_Hook4, swimSpeed * 1.3F, 0.35F, false, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.flap(this.LowerL_Hook, swimSpeed * 0.2F, 0.35F, false, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.swing(this.LowerL_Hook2, swimSpeed * 0.2F, 0.35F, false, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.swing(this.LowerL_Hook3, swimSpeed * 0.2F, 0.35F, true, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.flap(this.LowerL_Hook4, swimSpeed * 0.2F, 0.35F, true, 0.0F, -0.35F, ageInTicks, 1.0F);
      this.flap(this.LowerL_Hook, swimSpeed * 1.3F, 0.35F, false, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.swing(this.LowerL_Hook2, swimSpeed * 1.3F, 0.35F, false, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.swing(this.LowerL_Hook3, swimSpeed * 1.3F, 0.35F, true, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.flap(this.LowerL_Hook4, swimSpeed * 1.3F, 0.35F, true, 0.0F, -0.35F, limbSwing, limbSwingAmount);
      this.chainSwing(tailBoxes, swimSpeed * 0.4F, swimDegree * 0.45F, -1.0, ageInTicks, 1.0F);
      this.chainSwing(tailBoxes, swimSpeed * 4.0F, swimDegree * 0.6F, -1.0, limbSwing, limbSwingAmount);
      if (NoswimProgress <= 0.0F) {
         this.flap(this.R_fin, finspeed * 0.8F, finDegree, false, 0.0F, -0.2F, ageInTicks, 1.0F);
         this.flap(this.R_fin2, finspeed * 0.8F, finDegree, false, 1.0F, -0.2F, ageInTicks, 1.0F);
         this.flap(this.L_fin, finspeed * 0.8F, finDegree, true, 0.0F, -0.2F, ageInTicks, 1.0F);
         this.flap(this.L_fin2, finspeed * 0.8F, finDegree, true, 1.0F, -0.2F, ageInTicks, 1.0F);
         this.flap(this.R_fin, finspeed * 4.0F, finDegree, false, 0.0F, -0.2F, limbSwing, limbSwingAmount);
         this.flap(this.R_fin2, finspeed * 4.0F, finDegree, false, 1.0F, -0.2F, limbSwing, limbSwingAmount);
         this.flap(this.L_fin, finspeed * 4.0F, finDegree, true, 0.0F, -0.2F, limbSwing, limbSwingAmount);
         this.flap(this.L_fin2, finspeed * 4.0F, finDegree, true, 1.0F, -0.2F, limbSwing, limbSwingAmount);
         this.flap(this.R_mini_fin, finspeed * 1.2F, finDegree * 2.5F, false, 0.0F, -0.5F, ageInTicks, 1.0F);
         this.flap(this.L_mini_fin, finspeed * 1.2F, finDegree * 2.5F, true, 0.0F, -0.5F, ageInTicks, 1.0F);
         this.flap(this.R_down_fin, finspeed * 0.8F, finDegree * 1.5F, false, 0.0F, -0.3F, ageInTicks, 1.0F);
         this.flap(this.L_down_fin, finspeed * 0.8F, finDegree * 1.5F, true, 0.0F, -0.3F, ageInTicks, 1.0F);
         this.flap(this.R_mini_fin, finspeed * 4.0F, finDegree * 2.5F, false, 0.0F, -0.5F, limbSwing, limbSwingAmount);
         this.flap(this.L_mini_fin, finspeed * 4.0F, finDegree * 2.5F, true, 0.0F, -0.5F, limbSwing, limbSwingAmount);
         this.flap(this.R_down_fin, finspeed * 4.0F, finDegree * 1.5F, false, 0.0F, -0.3F, limbSwing, limbSwingAmount);
         this.flap(this.L_down_fin, finspeed * 4.0F, finDegree * 1.5F, true, 0.0F, -0.3F, limbSwing, limbSwingAmount);
      } else {
         this.swing(this.R_fin, finspeed * 20.0F, finDegree * 1.5F, false, 0.0F, -0.1F, limbSwing, limbSwingAmount);
         this.swing(this.L_fin, finspeed * 20.0F, finDegree * 1.5F, true, 0.0F, -0.1F, limbSwing, limbSwingAmount);
      }

      this.walk(this.Mouth, finspeed * 0.8F, finDegree * 0.15F, false, 0.0F, -0.03F, ageInTicks, 1.0F);
      this.walk(this.Mouth2, finspeed * 0.8F, finDegree * 0.15F, false, 0.0F, -0.03F, ageInTicks, 1.0F);
      this.walk(this.Mouth3, finspeed * 0.8F, finDegree * 0.15F, true, 0.0F, -0.03F, ageInTicks, 1.0F);
      this.walk(this.Mouth4, finspeed * 0.8F, finDegree * 0.15F, true, 0.0F, -0.03F, ageInTicks, 1.0F);
      this.walk(this.Maw, finspeed * 1.1F, finDegree * 0.15F, true, 0.0F, -0.03F, limbSwing, limbSwingAmount);
      this.walk(this.Skul, finspeed * 1.1F, finDegree * 0.15F, false, 0.0F, -0.03F, limbSwing, limbSwingAmount);
      AdvancedModelBox[] URT = new AdvancedModelBox[]{this.UpperR_Tentacle, this.UpperR_Tentacle2, this.UpperR_Tentacle3};
      AdvancedModelBox[] ULT = new AdvancedModelBox[]{this.UpperL_Tentacle, this.UpperL_Tentacle2, this.UpperL_Tentacle3};
      AdvancedModelBox[] LRT = new AdvancedModelBox[]{this.LowerR_Tentacle, this.LowerR_Tentacle2, this.LowerR_Tentacle3};
      AdvancedModelBox[] LLT = new AdvancedModelBox[]{this.LowerL_Tentacle, this.LowerL_Tentacle2, this.LowerL_Tentacle3};
      this.chainWave(URT, 0.03F, -0.1F, -3.0, ageInTicks, 1.0F);
      this.chainSwing(URT, 0.03F, -0.1F, -3.0, ageInTicks, 1.0F);
      this.chainWave(ULT, 0.03F, 0.1F, -3.0, ageInTicks, 1.0F);
      this.chainSwing(ULT, 0.03F, 0.1F, -3.0, ageInTicks, 1.0F);
      this.chainWave(LRT, 0.03F, -0.1F, -3.0, ageInTicks, 1.0F);
      this.chainSwing(LRT, 0.03F, -0.1F, -3.0, ageInTicks, 1.0F);
      this.chainWave(LLT, 0.03F, 0.1F, -3.0, ageInTicks, 1.0F);
      this.chainSwing(LLT, 0.03F, 0.1F, -3.0, ageInTicks, 1.0F);
      this.chainSwing(URT, 0.2F, -0.2F, -3.0, limbSwing, limbSwingAmount);
      this.chainWave(URT, 0.2F, -0.2F, -3.0, limbSwing, limbSwingAmount);
      this.chainSwing(ULT, 0.2F, 0.2F, -3.0, limbSwing, limbSwingAmount);
      this.chainWave(ULT, 0.2F, 0.2F, -3.0, limbSwing, limbSwingAmount);
      this.chainSwing(LRT, 0.2F, -0.2F, -3.0, limbSwing, limbSwingAmount);
      this.chainWave(LRT, 0.2F, -0.2F, -3.0, limbSwing, limbSwingAmount);
      this.chainSwing(LLT, 0.2F, 0.2F, -3.0, limbSwing, limbSwingAmount);
      this.chainWave(LLT, 0.2F, 0.2F, -3.0, limbSwing, limbSwingAmount);
      this.body.rotateAngleX += headPitch * (float) (Math.PI / 180.0);
      this.body.rotateAngleY += netHeadYaw * (float) (Math.PI / 180.0);
      if (horizontalMag(entityIn.getDeltaMovement()) > 1.0E-7) {
      }
   }

